#pragma once

#include <cstdint>
#include <string>
#include <memory>

// A simulated two-level cache (L1 and L2) in front of DRAM. Its code is in cache.a.
struct cache {
    virtual ~cache() = default;
    // Reads one byte at address addr and returns how many cycles the read took.
    virtual std::uint16_t read(std::uint32_t addr) noexcept = 0;
    // Empties both levels, as if no address had been read yet.
    virtual void reset() noexcept                           = 0;
    // Removes the line that holds addr from L1 only (or from L2 only). Nothing else changes: the line
    // is not moved to the other level, and the other lines keep their LRU order. No effect if absent.
    virtual void remove_from_l1(std::uint32_t addr) noexcept = 0;
    virtual void remove_from_l2(std::uint32_t addr) noexcept = 0;
};

// roll_num must be 2Nb0900..2Nb1200 (lowercase b) with N = 3, 4 or 5, or one listed exception;
// otherwise throws std::invalid_argument
std::unique_ptr<cache> make_part_a(std::string roll_num);

// Builds a cache with the given parameters; throws std::invalid_argument if they break a rule.
std::unique_ptr<cache> make_part_b(std::uint16_t cache_line_size,
                   std::uint16_t l1_num_set, std::uint16_t l1_num_way, std::uint16_t l1_latency,
                   std::uint16_t l2_num_set, std::uint16_t l2_num_way, std::uint16_t l2_latency,
                   std::uint16_t dram_latency);

// The eight parameters of a cache. A level's size is cache_line_size * num_set * num_way bytes.
struct cache_info {
    std::uint16_t cache_line_size; // bytes per line
    std::uint32_t l1_cache_size;   // bytes in L1
    std::uint16_t l1_num_way;
    std::uint16_t l1_latency;      // cycles for a read that hits in L1
    std::uint32_t l2_cache_size;   // bytes in L2
    std::uint16_t l2_num_way;
    std::uint16_t l2_latency;      // cycles for a read that misses L1 and hits in L2
    std::uint16_t dram_latency;    // cycles for a read that misses both levels
};

// Part A, in cache_info.cpp: the parameters of the cache of your roll number.
cache_info part_a();

// In cache_info.cpp, NOT graded: your own experiments. make task3 args="probe_parta ROLL" calls it once
// on an empty cache of ROLL (or demo); read from c in any pattern and print whatever you need.
void probe_parta(cache* c);

// Part B, in cache_info.cpp: each function finds the fields in its name and writes them into info.
// It may read the fields found by the functions that run before it (see find_order); the others are 0.
void find_l1_latency(cache* c, cache_info& info);    // l1_latency
void find_l2_latency(cache* c, cache_info& info);    // l2_latency
void find_dram_latency(cache* c, cache_info& info);  // dram_latency
void find_line_size(cache* c, cache_info& info);     // cache_line_size
void find_l1_num_way(cache* c, cache_info& info);    // l1_num_way
void find_l1_cache_size(cache* c, cache_info& info); // l1_cache_size
void find_l2_num_way(cache* c, cache_info& info);    // l2_num_way
void find_l2_cache_size(cache* c, cache_info& info); // l2_cache_size

// Part B, in cache_info.cpp: the order in which get_cache_info runs the eight functions. It must name
// each of them exactly once; you may change the order.
using finder = void (*)(cache* c, cache_info& info);
extern finder const find_order[8];

// Provided in main.cpp: starts from an all-zero cache_info and runs the functions of find_order in
// order, calling c->reset() before each one, so every function starts from an empty cache.
cache_info get_cache_info(cache* c);
